adapter.UpdateCommand = new SqlCommand(
    "UPDATE Customers SET CompanyName=@CompanyName " +
    "WHERE CustomerID=@oldCustomerID AND CompanyName=@oldCompanyName", conn);
var p = adapter.UpdateCommand.Parameters.Add(
    "@oldCompanyName", SqlDbType.NVarChar, 30, "CompanyName");
p.SourceVersion = DataRowVersion.Original;      // original values in WHERE
adapter.RowUpdated += (s, e) => {
    if (e.RecordsAffected == 0)
        e.Row.RowError = "Optimistic Concurrency Violation!";
};

